from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for i in (1,2,5,6,7,10,16,17):
    print('\\nPAGE',i+1)
    urls=[]
    for a in r.pages[i].get('/Annots',[]):
        d=a.get_object().get('/A',{})
        if hasattr(d,'get_object'): d=d.get_object()
        if '/URI' in d:
            u=str(d['/URI'])
            if u not in urls: urls.append(u)
    for u in urls[:15]: print(u)
    print('URL count',len(urls))
